### LoginForm.tsx
```tsx
import React, { useState } from 'react';
import { EyeIcon, EyeOffIcon } from 'lucide-react';

export interface LoginFormProps {
  onSubmit: (email: string, password: string) => void;
  isLoading: boolean;
}

export function LoginForm({ onSubmit, isLoading }: LoginFormProps) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [emailError, setEmailError] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  const validateEmail = (email: string): boolean => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
  };

  const validatePassword = (password: string): boolean => {
    return password.length >= 6;
  };

  const handleEmailChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setEmail(e.target.value);
    if (emailError) setEmailError('');
  };

  const handlePasswordChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setPassword(e.target.value);
    if (passwordError) setPasswordError('');
  };

  const togglePasswordVisibility = () => {
    setShowPassword(!showPassword);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const emailValid = validateEmail(email);
    const passwordValid = validatePassword(password);

    if (!emailValid) setEmailError('Please enter a valid email address.');
    if (!passwordValid) setPasswordError('Password must be at least 6 characters long.');

    if (emailValid && passwordValid) {
      onSubmit(email, password);
    }
  };

  const isFormValid = validateEmail(email) && validatePassword(password);

  return (
    <form onSubmit={handleSubmit} className="max-w-sm w-full space-y-6">
      <div>
        <label htmlFor="email" className="block text-sm font-medium text-slate-700 mb-1">
          Email
        </label>
        <input
          id="email"
          type="email"
          value={email}
          onChange={handleEmailChange}
          className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent transition-colors ${
            emailError ? 'border-red-300 bg-red-50' : 'border-slate-300 focus:ring-accent'
          }`}
          placeholder="you@example.com"
        />
        {emailError && (
          <p className="mt-1 text-sm text-red-500 flex items-center gap-1">
            <span className="text-red-500">⚠</span>
            {emailError}
          </p>
        )}
      </div>

      <div>
        <label htmlFor="password" className="block text-sm font-medium text-slate-700 mb-1">
          Password
        </label>
        <div className="relative">
          <input
            id="password"
            type={showPassword ? 'text' : 'password'}
            value={password}
            onChange={handlePasswordChange}
            className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-accent transition-colors ${
              passwordError ? 'border-red-300 bg-red-50' : 'border-slate-300 focus:ring-accent'
            }`}
            placeholder="••••••••"
          />
          <button
            type="button"
            onClick={togglePasswordVisibility}
            className="absolute inset-y-0 right-0 flex items-center pr-3 text-slate-500 hover:text-accent transition-colors"
            aria-label={showPassword ? 'Hide password' : 'Show password'}
          >
            {showPassword ? <EyeOffIcon size={18} /> : <EyeIcon size={18} />}
          </button>
        </div>
        {passwordError && (
          <p className="mt-1 text-sm text-red-500 flex items-center gap-1">
            <span className="text-red-500">⚠</span>
            {passwordError}
          </p>
        )}
      </div>

      <button
        type="submit"
        disabled={!isFormValid || isLoading}
        className={`w-full py-3 rounded-lg font-medium text-white transition-all ${
          isFormValid && !isLoading
            ? 'bg-accent hover:bg-purple-600 focus:ring-4 focus:ring-accent/30'
            : 'bg-slate-300 cursor-not-allowed'
        }`}
      >
        {isLoading ? 'Logging in...' : 'Log In'}
      </button>
    </form>
  );
}
